module E = Errormsg

let parse_error msg : unit =       (* sm: c++-mode highlight hack: -> ' <- *)
  E.parse_error msg
let parse_warn msg : unit =       (* sm: c++-mode highlight hack: -> ' <- *)
  E.parse_warn msg

